using System.ClientModel;
using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tools ---
var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(
    (string query) =>
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();
        return WebSearcher.SearchAsync(query);
    },
    "web_search",
    "Searches the web for the given query and returns a list of result snippets.");

var addNoteTool = AIFunctionFactory.Create(
    ([Description("A concise note capturing a key finding")] string note) =>
    {
        notebook.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  📝 Note added ({notebook.Count} total)");
        Console.ResetColor();
        return $"Note saved. You now have {notebook.Count} note(s).";
    },
    "add_note",
    "Saves a research note for later use in the summary.");

var readNotesTool = AIFunctionFactory.Create(
    () =>
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  📖 Reading notes ({notebook.Count})");
        Console.ResetColor();
        return notebook.Count == 0
            ? "No notes yet."
            : string.Join("\n", notebook.Notes.Select((n, i) => $"{i + 1}. {n}"));
    },
    "read_notes",
    "Returns all research notes collected so far.");

// --- Chat client with automatic tool invocation ---
IChatClient client = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [searchTool, addNoteTool, readNotesTool],
    Temperature = 0.3f
};

// --- Agent system prompt ---
const string SystemPrompt = """
    You are a research agent. Given a topic you will:
    1. Search the web 2-3 times with varied queries to gather diverse information.
    2. After each search, save the most important findings as notes using add_note.
    3. When you have enough material, read your notes with read_notes.
    4. Produce a well-structured markdown summary with sections, key facts, and sources.
    Be thorough but concise. Always cite where information came from.
    """;

// --- Main loop ---
Console.WriteLine("╔═══════════════════════════════════════╗");
Console.WriteLine("║       🔬  AI Research Agent  🔬       ║");
Console.WriteLine("╠═══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or       ║");
Console.WriteLine("║  type 'quit' to exit.                 ║");
Console.WriteLine("╚═══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, SystemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary:\n\n{topic}")
    };

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Agent is researching... (tool calls will appear below)");
    Console.ResetColor();
    Console.WriteLine();

    var response = await client.GetResponseAsync(messages, chatOptions);

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.White;
    Console.WriteLine("═══════════════ RESEARCH SUMMARY ═══════════════");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine("═════════════════════════════════════════════════");
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

