/// <summary>Performs web searches using the Bing Search API or falls back to a simple scraper.</summary>
static class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } }
    };

    public static async Task<string> SearchAsync(string query)
    {
        // Use Bing Web Search API if key is available, otherwise use DuckDuckGo HTML
        var bingKey = Environment.GetEnvironmentVariable("BING_SEARCH_API_KEY");
        if (!string.IsNullOrEmpty(bingKey))
            return await BingSearchAsync(query, bingKey);

        return await DuckDuckGoLiteAsync(query);
    }

    private static async Task<string> BingSearchAsync(string query, string apiKey)
    {
        var url = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5";
        using var req = new HttpRequestMessage(HttpMethod.Get, url);
        req.Headers.Add("Ocp-Apim-Subscription-Key", apiKey);
        using var resp = await Http.SendAsync(req);
        resp.EnsureSuccessStatusCode();
        var json = await resp.Content.ReadAsStringAsync();
        return json;
    }

    private static async Task<string> DuckDuckGoLiteAsync(string query)
    {
        try
        {
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            using var req = new HttpRequestMessage(HttpMethod.Get, url);
            req.Headers.Add("Accept", "text/html");
            using var resp = await Http.SendAsync(req);
            resp.EnsureSuccessStatusCode();
            var html = await resp.Content.ReadAsStringAsync();

            // Extract result snippets from the HTML
            var results = new List<string>();
            var snippetTag = "class=\"result__snippet\"";
            var idx = 0;
            while (results.Count < 5 && (idx = html.IndexOf(snippetTag, idx, StringComparison.Ordinal)) != -1)
            {
                idx = html.IndexOf('>', idx) + 1;
                var end = html.IndexOf('<', idx);
                if (end > idx)
                {
                    var text = System.Net.WebUtility.HtmlDecode(html[idx..end]).Trim();
                    if (text.Length > 20)
                        results.Add(text);
                }
            }

            // Also grab result titles and URLs
            var titleTag = "class=\"result__a\"";
            var titles = new List<string>();
            idx = 0;
            while (titles.Count < 5 && (idx = html.IndexOf(titleTag, idx, StringComparison.Ordinal)) != -1)
            {
                // Extract href
                var hrefStart = html.LastIndexOf("href=\"", idx, Math.Min(idx, 200), StringComparison.Ordinal);
                var hrefUrl = "";
                if (hrefStart != -1)
                {
                    hrefStart += 6;
                    var hrefEnd = html.IndexOf('"', hrefStart);
                    if (hrefEnd > hrefStart)
                        hrefUrl = html[hrefStart..hrefEnd];
                }

                idx = html.IndexOf('>', idx) + 1;
                var end = html.IndexOf('<', idx);
                if (end > idx)
                {
                    var title = System.Net.WebUtility.HtmlDecode(html[idx..end]).Trim();
                    titles.Add($"{title} ({hrefUrl})");
                }
            }

            if (results.Count == 0 && titles.Count == 0)
                return "No search results found. Try rephrasing the query.";

            var output = new System.Text.StringBuilder();
            for (var i = 0; i < Math.Max(results.Count, titles.Count); i++)
            {
                output.AppendLine($"Result {i + 1}:");
                if (i < titles.Count) output.AppendLine($"  Title: {titles[i]}");
                if (i < results.Count) output.AppendLine($"  Snippet: {results[i]}");
                output.AppendLine();
            }

            return output.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

